 1	import {createChatOrchestrator} from './chatOrchestrator.js';
 2	import type {AIProvider, MessageChunk} from '../types/ai.js';
 3	import type {ChatSession} from '../types/session.js';
 4	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
 5	
 6	// specs/hal-engine-config-hooks/spec.md#7
 7	it('runs error and cleanup hooks in order after beforeSession fails', async () => {
 8	  const session: ChatSession = {
 9	    sessionId: 's1',
10	    userId: 'u1',
11	    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
12	  };
13	  const failure = new Error('setup failed');
14	  const calls: string[] = [];
15	  let beforeSessionSession: ChatSession | undefined;
16	  let onErrorSession: ChatSession | undefined;
17	  let onErrorFailure: Error | undefined;
18	  let afterSessionSession: ChatSession | undefined;
19	  const provider: AIProvider = {
20	    async *sendMessage(): AsyncGenerator<MessageChunk> {
21	      calls.push('provider');
22	      yield {type: 'stop', stopReason: 'end_turn'};
23	    },
24	    async generateStructured<T>(): Promise<T> {
25	      return {} as T;
26	    },
27	  };
28	  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), undefined, {
29	    hooks: {
30	      beforeSession: async received => {
31	        beforeSessionSession = received;
32	        calls.push('beforeSession');
33	        throw failure;
34	      },
35	      beforeUserInput: async (_received, message) => {
36	        calls.push('beforeUserInput');
37	        return message;
38	      },
39	      onError: async (received, error) => {
40	        onErrorSession = received;
41	        onErrorFailure = error;
42	        calls.push('onError');
43	      },
44	      afterSession: async received => {
45	        afterSessionSession = received;
46	        calls.push('afterSession');
47	      },
48	    },
49	  });
50	
51	  const rejectedWith = await orchestrator.processMessage(session).then(
52	    () => undefined,
53	    error => error
54	  );
55	  expect({rejectedWith, calls, beforeSessionSession, onErrorSession, onErrorFailure, afterSessionSession}).toEqual({
56	    rejectedWith: failure,
57	    calls: ['beforeSession', 'onError', 'afterSession'],
58	    beforeSessionSession: session,
59	    onErrorSession: session,
60	    onErrorFailure: failure,
61	    afterSessionSession: session,
62	  });
63	});

